{
  "packages": [
    "npm:pi-lsp@0.1.7",
    "npm:pi-rtk-optimizer@0.9.0"
  ]
}

{
  "npm": {
    "pi-lsp": "0.1.7",
    "pi-rtk-optimizer": "0.9.0"
  }
}

{
  "name": "pi-lsp",
  "version": "0.1.7",
  "description": "Declarative Pi extension for LSP diagnostics and language-server navigation tools.",
  "type": "module",
  "license": "MIT",
  "keywords": [
    "pi-package",
    "pi",
    "lsp",
    "language-server",
    "diagnostics"
  ],
  "engines": {
    "node": ">=20"
  },
  "files": [
    "extensions",
    "README.md",
    "LICENSE"
  ],
  "pi": {
    "extensions": [
      "extensions/pi-lsp/index.ts"
    ]
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "verify": "npm run typecheck && npm test",
    "prepack": "npm run verify"
  },
  "dependencies": {
    "vscode-jsonrpc": "^8.2.1",
    "vscode-languageserver-protocol": "^3.17.5"
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": "*",
    "@earendil-works/pi-tui": "*",
    "typebox": "*"
  },
  "devDependencies": {
    "@types/node": "^24.0.0",
    "typescript": "^5.8.0",
    "vitest": "^3.0.0"
  }
}

vim.lsp.config("pyrefly", {
    settings = {
        python = {
            analysis = {
                typeCheckingMode = "basic",
                autoSearchPaths = true,
                useLibraryCodeForTypes = true,
            },
        },
    },
})
vim.lsp.enable("pyrefly")

vim.lsp.config("clangd", {
    cmd = {
        "clangd",
        "--clang-tidy",
        "--completion-style=detailed",
        "--header-insertion=iwyu",
        "--query-driver=cc,/run/current-system/sw/bin/cc,/run/current-system/sw/bin/clang,/run/current-system/sw/bin/clang++,/run/current-system/sw/bin/gcc,/run/current-system/sw/bin/g++,/nix/store/*/bin/cc,/nix/store/*/bin/clang,/nix/store/*/bin/clang++,/nix/store/*/bin/gcc,/nix/store/*/bin/g++,/nix/store/*devkitARM*/opt/devkitpro/devkitARM/bin/arm-none-eabi-*",
    },
    capabilities = {
        offsetEncoding = { "utf-16" },
    },
    root_markers = {
        "compile_commands.json",
        "compile_flags.txt",
        "configure.ac", -- AutoTools
        "Makefile",
        "configure.ac",
        "configure.in",
        "config.h.in",
        "meson.build",
        "meson_options.txt",
        "build.ninja",
        ".git",
    },
})
vim.lsp.enable("clangd")

vim.api.nvim_create_autocmd("FileType", {
    pattern = { "c", "cpp" },
    callback = function()
        vim.keymap.set(
            "n",
            "<localleader>s",
            "<cmd>ClangdSwitchSourceHeader<CR>",
            { buffer = true, desc = "Switch Source/Header" }
        )
    end,
})

{...}: {
	flake.modules.homeManager.pi = {pkgs, ...}: let
		language_servers = with pkgs; [
			clang-tools
			pyrefly
			slang-server
		];
	in {
		programs.pi-coding-agent = {
			enable = true;
			extraPackages = with pkgs; [nodejs bun rtk] ++ language_servers;
		};

		# home.file.".pi".source = osConfig._module.args.impurity.link piConfig;
	};
}
